 78→// updateStrategyOptions applies strategy flags to settings without re-running agent setup.
 79→// Loads and writes only the target file to avoid leaking settings between layers.
 80→func updateStrategyOptions(ctx context.Context, w io.Writer, opts EnableOptions) error {
 81→	// Validate before doing any I/O so we don't report "Settings updated" on bad input.
 82→	if opts.CheckpointRemote != "" {
 83→		if _, _, err := parseCheckpointRemoteFlag(opts.CheckpointRemote); err != nil {
 84→			return fmt.Errorf("invalid --checkpoint-remote: %w", err)
 85→		}
 86→	}
 87→
 88→	targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
 89→
 90→	targetFileAbs, err := paths.AbsPath(ctx, targetFile)
 91→	if err != nil {
 92→		targetFileAbs = targetFile
 93→	}
 94→
 95→	s, err := settings.LoadFromFile(targetFileAbs)
 96→	if err != nil {
 97→		return fmt.Errorf("failed to load settings: %w", err)
 98→	}
 99→
100→	opts.applyStrategyOptions(s)
101→
102→	if targetFile == settings.EntireSettingsLocalFile {
103→		if err := SaveEntireSettingsLocal(ctx, s); err != nil {
104→			return fmt.Errorf("failed to save settings: %w", err)
105→		}
106→	} else {
107→		if err := SaveEntireSettings(ctx, s); err != nil {
108→			return fmt.Errorf("failed to save settings: %w", err)
109→		}
110→	}
111→
112→	fmt.Fprintf(w, "✓ Settings updated (%s)\n", configDisplay)
113→	return nil
114→}
