	got := styOff.render(style, "test")
	if got != "test" {
		t.Errorf("render(colorEnabled=false) = %q, want exact %q", got, "test")
	}

	// Color enabled: exercises style.Render code path, text preserved
	styOn := statusStyles{colorEnabled: true}
