func TestTotalTokens(t *testing.T) {
	t.Parallel()

	t.Run("nil", func(t *testing.T) {
		t.Parallel()
		if got := totalTokens(nil); got != 0 {
			t.Errorf("totalTokens(nil) = %d, want 0", got)
		}
	})

	t.Run("basic", func(t *testing.T) {
		t.Parallel()
		tu := &agent.TokenUsage{
			InputTokens:  100,
			OutputTokens: 50,
		}
		if got := totalTokens(tu); got != 150 {
