		t.Parallel()
		tu := &agent.TokenUsage{
			InputTokens:  100,
			OutputTokens: 50,
			SubagentTokens: &agent.TokenUsage{
				InputTokens:  200,
				OutputTokens: 100,
			},
		}
		if got := totalTokens(tu); got != 450 {
			t.Errorf("totalTokens() = %d, want 450", got)
